"""
The semiprime pair-law audit: how a product of two primes exposes a labelling error
that no single prime can see.

For the quintic x^5 - 2 the two residue classes p = 2 and p = 3 (mod 5) both produce the
splitting shape [1,4].  Swapping which class is which therefore changes nothing that a
single prime can reveal — but the dial of a semiprime N = p q is the SUM of the two hidden
classes, and addition notices the difference: the pair law moves from 5/4 to 9/8.

Self-contained; no third-party dependencies.  Run:  python3 pair_audit.py
"""

from __future__ import annotations

import math
import random
from typing import Callable, Dict, Hashable, List, Sequence, Tuple


def ent(counts: Sequence[int]) -> float:
    tot = sum(counts)
    return -sum((c / tot) * math.log2(c / tot) for c in counts if c > 0)


def mutual_information(samples: Sequence[Tuple[Hashable, Hashable]]) -> float:
    a: Dict[Hashable, int] = {}
    b: Dict[Hashable, int] = {}
    j: Dict[Tuple[Hashable, Hashable], int] = {}
    for u, v in samples:
        a[u] = a.get(u, 0) + 1
        b[v] = b.get(v, 0) + 1
        j[(u, v)] = j.get((u, v), 0) + 1
    return ent(list(a.values())) + ent(list(b.values())) - ent(list(j.values()))


def quintic_type(x: int, swapped: bool = False) -> str:
    """Splitting type at the Frobenius class x = 5e + b of the field of x^5 - 2.
    `swapped` puts [1,2,2] on the coset e = 3 instead of e = 2 — the bookkeeping error."""
    e, b = x // 5, x % 5
    if e == 0:
        return "[1^5]" if b == 0 else "[5]"
    if not swapped:
        return "[1,2,2]" if e == 2 else "[1,4]"
    return "[1,2,2]" if e == 3 else "[1,4]"


def dial(x: int) -> int:
    """The C4 valuation of the multiplier, i.e. p mod 5 through the discrete logarithm."""
    return x // 5


def exact_prime_channel(swapped: bool) -> float:
    return mutual_information([(quintic_type(x, swapped), dial(x)) for x in range(20)])


def exact_pair_channel(swapped: bool, unordered: bool = False) -> float:
    data: List[Tuple[Hashable, int]] = []
    for x in range(20):
        for y in range(20):
            t1, t2 = quintic_type(x, swapped), quintic_type(y, swapped)
            key: Hashable = tuple(sorted([t1, t2])) if unordered else (t1, t2)
            data.append((key, (dial(x) + dial(y)) % 4))
    return mutual_information(data)


def monte_carlo_pair_channel(samples: int = 400_000, seed: int = 20250916) -> float:
    rng = random.Random(seed)
    data: List[Tuple[Hashable, int]] = []
    for _ in range(samples):
        x, y = rng.randrange(20), rng.randrange(20)
        data.append(((quintic_type(x), quintic_type(y)), (dial(x) + dial(y)) % 4))
    return mutual_information(data)


def fork_channel() -> float:
    """The [1,2,2]-fork: how many of the two factors satisfy p = 4 mod 5."""
    data = [(int(quintic_type(x) == "[1,2,2]") + int(quintic_type(y) == "[1,2,2]"),
             (dial(x) + dial(y)) % 4) for x in range(20) for y in range(20)]
    return mutual_information(data)


def main() -> None:
    print("           quantity                     correct labelling    swapped labelling")
    print("  " + "-" * 76)
    print(f"  I(type ; p mod 5)                      {exact_prime_channel(False):.6f}"
          f"             {exact_prime_channel(True):.6f}      <- identical")
    print(f"  I(ordered pair ; N mod 5)              {exact_pair_channel(False):.6f}"
          f"             {exact_pair_channel(True):.6f}      <- 1/8 bit apart")
    print(f"  I(unordered pair ; N mod 5)            {exact_pair_channel(False, True):.6f}"
          f"             {exact_pair_channel(True, True):.6f}")
    print()
    print(f"  which-factor wall (ordered - unordered) = "
          f"{exact_pair_channel(False) - exact_pair_channel(False, True):.6f}")
    print(f"  [1,2,2]-fork, I(split count ; N mod 5)  = {fork_channel():.6f}"
          f"   closed form 19/8 - (21/16)log2 3 = {19/8 - (21/16)*math.log2(3):.6f}")
    print()
    mc = monte_carlo_pair_channel()
    print(f"  Monte Carlo (400000 semiprimes, fixed seed): {mc:.4f}")
    print(f"     distance to the correct law 5/4 = {abs(mc - 1.25):.4f}")
    print(f"     distance to the swapped law 9/8 = {abs(mc - 1.125):.4f}   <- decisively excluded")


if __name__ == "__main__":
    main()

