"""Algorithm A — exact evaluation of a splitting-type channel from a Chebotarev box."""

from __future__ import annotations

import math
from typing import Callable, Dict, Hashable, List, Sequence, Tuple


def entropy_of_counts(counts: Sequence[int]) -> float:
    """Shannon entropy in bits of a distribution given by non-negative counts."""
    total: int = sum(counts)
    return -sum((c / total) * math.log2(c / total) for c in counts if c > 0)


def channel_report(box: Sequence[Hashable],
                   typ: Callable[[Hashable], Hashable],
                   dial: Callable[[Hashable], Hashable]) -> Dict[str, float]:
    """Exact H(T), H(D), H(T,D), I(T;D), H(T|D), H(D|T) for a uniformly weighted box.

    Complexity: one pass over the box, O(|S|) time and O(|T| |D|) memory.
    """
    ct: Dict[Hashable, int] = {}
    cd: Dict[Hashable, int] = {}
    cj: Dict[Tuple[Hashable, Hashable], int] = {}
    for x in box:
        t, d = typ(x), dial(x)
        ct[t] = ct.get(t, 0) + 1
        cd[d] = cd.get(d, 0) + 1
        cj[(t, d)] = cj.get((t, d), 0) + 1

    HT = entropy_of_counts(list(ct.values()))
    HD = entropy_of_counts(list(cd.values()))
    HTD = entropy_of_counts(list(cj.values()))
    I = HT + HD - HTD
    return {"H(T)": HT, "H(D)": HD, "H(T,D)": HTD,
            "I(T;D)": I, "H(T|D)": HT - I, "H(D|T)": HD - I}


def product_channel_report(box: Sequence[Hashable],
                           typ: Callable[[Hashable], Hashable],
                           dial: Callable[[Hashable], int],
                           modulus: int,
                           unordered: bool = False) -> Dict[str, float]:
    """The semiprime layer: two independent draws, the dial of the product being the
    sum of the two dial classes in the cyclic group of order `modulus`.

    Complexity: O(|S|^2).
    """
    pairs: List[Tuple[Hashable, Hashable]] = [(x, y) for x in box for y in box]

    def pair_type(xy: Tuple[Hashable, Hashable]) -> Hashable:
        a, b = typ(xy[0]), typ(xy[1])
        return tuple(sorted([repr(a), repr(b)])) if unordered else (a, b)

    def prod_dial(xy: Tuple[Hashable, Hashable]) -> int:
        return (dial(xy[0]) + dial(xy[1])) % modulus

    return channel_report(pairs, pair_type, prod_dial)

"""Algorithm C — empirical validation of the law over genuine primes."""

from __future__ import annotations

import math
from typing import Dict, List, Tuple


def primes_up_to(n: int) -> List[int]:
    """Sieve of Eratosthenes, O(n log log n)."""
    sieve = bytearray([1]) * (n + 1)
    sieve[0:2] = b"\x00\x00"
    for p in range(2, int(n ** 0.5) + 1):
        if sieve[p]:
            sieve[p * p::p] = bytearray(len(sieve[p * p::p]))
    return [i for i in range(2, n + 1) if sieve[i]]


def radical_type(q: int, a: int, p: int) -> str:
    """The factorisation shape of x^q - a modulo an unramified prime p, for prime q,
    obtained without factoring: the multiplier order d = ord(p mod q) decides the shape,
    except in the class p = 1 mod q, where one extra power test says whether a is a
    q-th power mod p.  Cost: O(log p) modular multiplications.
    """
    r = p % q
    if r == 1:
        return "[1^%d]" % q if pow(a, (p - 1) // q, p) == 1 else "[%d]" % q
    d, cur = 1, r
    while cur != 1:
        cur = (cur * r) % q
        d += 1
    return "[1" + ",%d" % d * ((q - 1) // d) + "]"


def discrete_log_table(q: int) -> Dict[int, int]:
    """Residue mod q  ->  its C_{q-1} valuation, i.e. the dial class."""
    for g in range(2, q):
        powers = [pow(g, k, q) for k in range(q - 1)]
        if len(set(powers)) == q - 1:
            return {v: k for k, v in enumerate(powers)}
    raise ValueError("no primitive root")


def empirical_channel(q: int, a: int, limit: int) -> Dict[str, float]:
    """Plug-in estimates of H(T), H(D) and I(T;D) over the unramified primes below `limit`.

    Bias of the plug-in estimator is O(cells / #primes); with a few dozen cells and
    tens of thousands of primes it sits below 1e-3.
    """
    dlog = discrete_log_table(q)
    joint: Dict[Tuple[str, int], int] = {}
    for p in primes_up_to(limit):
        if p == q or a % p == 0:
            continue
        key = (radical_type(q, a, p), dlog[p % q])
        joint[key] = joint.get(key, 0) + 1

    def ent(counts: List[int]) -> float:
        tot = sum(counts)
        return -sum((c / tot) * math.log2(c / tot) for c in counts if c > 0)

    ct: Dict[str, int] = {}
    cd: Dict[int, int] = {}
    for (t, d), c in joint.items():
        ct[t] = ct.get(t, 0) + c
        cd[d] = cd.get(d, 0) + c
    HT, HD, HJ = ent(list(ct.values())), ent(list(cd.values())), ent(list(joint.values()))
    return {"primes": float(sum(joint.values())), "H(T)": HT, "H(D)": HD, "I(T;D)": HT + HD - HJ}
